package firmware

import (
	"context"
	"sync"
	"time"
)

// DeviceState represents the current state of an IoT sensor node
type DeviceState struct {
	mu          sync.Mutex
	calibration float64
	readings    []float64
	callbacks   []func(float64)
	committed   bool
	version     uint64
}

// CalibrationManager handles firmware calibration updates
type CalibrationManager struct {
	state    *DeviceState
	pending  chan calibrationRequest
	notifier *EventNotifier
}

type calibrationRequest struct {
	value    float64
	resultCh chan error
}

// EventNotifier dispatches state change events to registered handlers
type EventNotifier struct {
	state *DeviceState
}

func NewDeviceState() *DeviceState {
	return &DeviceState{
		calibration: 1.0,
		readings:    make([]float64, 0, 100),
		callbacks:   make([]func(float64), 0),
		committed:   true,
		version:     0,
	}
}

func NewCalibrationManager(state *DeviceState) *CalibrationManager {
	cm := &CalibrationManager{
		state:   state,
		pending: make(chan calibrationRequest, 16),
		notifier: &EventNotifier{state: state},
	}
	go cm.processLoop()
	return cm
}

// RegisterCallback adds a state-change observer
func (ds *DeviceState) RegisterCallback(cb func(float64)) {
	ds.mu.Lock()
	ds.callbacks = append(ds.callbacks, cb)
	ds.mu.Unlock()
}

// ApplyCalibration updates calibration while holding state lock
func (ds *DeviceState) ApplyCalibration(newCal float64) {
	ds.mu.Lock()
	ds.committed = false
	ds.calibration = newCal
	ds.version++
	ds.mu.Unlock()
}

// CommitState finalizes the current state transition
func (ds *DeviceState) CommitState() {
	ds.mu.Lock()
	ds.committed = true
	ds.mu.Unlock()
}

// ReadCalibration returns current calibration (used by callbacks)
func (ds *DeviceState) ReadCalibration() float64 {
	ds.mu.Lock()
	defer ds.mu.Unlock()
	return ds.calibration
}

// IsCommitted checks if state is finalized
func (ds *DeviceState) IsCommitted() bool {
	ds.mu.Lock()
	defer ds.mu.Unlock()
	return ds.committed
}

// notifyObservers dispatches to all registered callbacks
// CRITICAL: This acquires the state lock to read callbacks,
// then invokes each callback which may re-acquire the lock
func (en *EventNotifier) notifyObservers(newValue float64) {
	en.state.mu.Lock()
	// snapshot callbacks under lock
	cbs := make([]func(float64), len(en.state.callbacks))
	copy(cbs, en.state.callbacks)
	// Release lock before invoking callbacks to avoid deadlock
	en.state.mu.Unlock()

	for _, cb := range cbs {
		cb(newValue)
	}
}

// processLoop handles calibration requests sequentially
func (cm *CalibrationManager) processLoop() {
	for req := range cm.pending {
		cm.handleRequest(req)
	}
}

// handleRequest processes a single calibration update
// The state machine is: Apply -> Notify -> Commit
func (cm *CalibrationManager) handleRequest(req calibrationRequest) {
	// Step 1: Apply new calibration
	cm.state.ApplyCalibration(req.value)

	// Step 2: Notify observers of the pending change
	// Observers can read state and even submit new calibrations
	cm.notifier.notifyObservers(req.value)

	// Step 3: Commit the state
	// BUG: If a callback in Step 2 submitted a new calibration request
	// that was processed (reentrant via the channel), the commit here
	// finalizes a STALE state. The interleaving is:
	//   Apply(A) -> Notify(A) -> [callback triggers Apply(B) -> Notify(B) -> Commit(B)]
	//   -> Commit(A) overwrites committed=true for version that's already superseded
	cm.state.CommitState()

	req.resultCh <- nil
}

// RequestCalibration submits an async calibration update
func (cm *CalibrationManager) RequestCalibration(ctx context.Context, value float64) error {
	resultCh := make(chan error, 1)
	select {
	case cm.pending <- calibrationRequest{value: value, resultCh: resultCh}:
	case <-ctx.Done():
		return ctx.Err()
	}
	select {
	case err := <-resultCh:
		return err
	case <-ctx.Done():
		return ctx.Err()
	}
}

// SimulateSensorLoop mimics the main firmware loop
func SimulateSensorLoop(cm *CalibrationManager, state *DeviceState) {
	// Register a callback that triggers recalibration (common in IoT PID loops)
	state.RegisterCallback(func(newCal float64) {
		if newCal > 2.0 {
			// Feedback loop: high calibration triggers dampening
			// This re-enters the calibration pipeline
			ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
			defer cancel()
			// This sends to the buffered channel - if processLoop picks it up
			// before the outer handleRequest completes, we get reentrant state corruption
			cm.RequestCalibration(ctx, newCal*0.5)
		}
	})

	// Normal operation: periodic calibration updates
	for i := 0; i < 10; i++ {
		ctx := context.Background()
		cm.RequestCalibration(ctx, float64(i)*0.5+1.0)
		time.Sleep(10 * time.Millisecond)
	}
}
